$path = "C:\Users\Administrator\.claude\projects\E--project--------------\d80bda74-de4a-40c0-8adb-80b5b339b9fa\tool-results\mcp-playwright-browser_evaluate-1784624453788.txt"
$raw = [System.IO.File]::ReadAllText($path, [System.Text.Encoding]::UTF8)
# Save each section separately by URL keys
$outDir = "E:\project\亚马逊平台驾驶舱-店铺数据\_api_docs"
if (Test-Path $outDir) { Remove-Item $outDir -Recurse -Force }
New-Item -ItemType Directory -Path $outDir | Out-Null

# The result is a JSON-like object with URL keys - try parse as JSON from after ### Result
if ($raw -match '(?s)### Result\r?\n(.+)$') { $jsonish = $Matches[1].Trim() } else { $jsonish = $raw }

# Playwright may wrap as plain object text. Try JSON parse
try {
  $obj = $jsonish | ConvertFrom-Json
  foreach ($p in $obj.PSObject.Properties) {
    $name = ($p.Name -replace 'https://sellfoxapi\.apifox\.cn/','' -replace '[\\/:]','_')
    $file = Join-Path $outDir ($name + '.md')
    [System.IO.File]::WriteAllText($file, $p.Value, [System.Text.UTF8Encoding]::new($false))
    Write-Host "Wrote" $name "len" $p.Value.Length
  }
} catch {
  Write-Host "JSON parse failed:" $_.Exception.Message
  # fallback: write raw head
  [System.IO.File]::WriteAllText((Join-Path $outDir 'raw.txt'), $jsonish.Substring(0, [Math]::Min(5000,$jsonish.Length)))
}
Get-ChildItem $outDir | Format-Table Name, Length

