async () => {
  const urls = [
    'https://sellfoxapi.apifox.cn/doc-1749562.md',
    'https://sellfoxapi.apifox.cn/doc-8966970.md',
    'https://sellfoxapi.apifox.cn/api-51516618.md',
    'https://sellfoxapi.apifox.cn/api-119107035.md',
    'https://sellfoxapi.apifox.cn/api-51516604.md',
    'https://sellfoxapi.apifox.cn/api-146414432.md',
    'https://sellfoxapi.apifox.cn/api-248307071.md',
    'https://sellfoxapi.apifox.cn/api-367482277.md',
    'https://sellfoxapi.apifox.cn/api-420168353.md',
    'https://sellfoxapi.apifox.cn/doc-1749600.md',
    'https://sellfoxapi.apifox.cn/doc-1759053.md',
    'https://sellfoxapi.apifox.cn/api-474651907.md',
  ];
  // write to window global in chunks via localStorage
  const out = {};
  for (const u of urls) {
    try {
      const r = await fetch(u, { credentials: 'include' });
      out[u] = await r.text();
    } catch (e) {
      out[u] = 'ERR:' + e.message;
    }
  }
  // store full on window
  window.__apiDocs = out;
  return Object.fromEntries(Object.entries(out).map(([k,v]) => [k, {len: v.length, head: v.slice(0, 500)}]));
}

() => {
  const docs = window.__apiDocs || {};
  const get = (u) => docs[u] || '';
  // Extract path + key body fields from openapi md
  function extractApi(md) {
    const path = (md.match(/paths:\n\s+(\/api\/[^\n:]+):/) || [])[1] || '';
    // grab required query params and body properties (first level keys near properties)
    const bodyKeys = [];
    const m = md.match(/requestBody:[\s\S]*?properties:\n([\s\S]*?)(?:required:|examples:|security:|x-)/);
    if (m) {
      const lines = m[1].split('\n');
      for (const line of lines) {
        const km = line.match(/^          ([a-zA-Z0-9_]+):/);
        if (km) bodyKeys.push(km[1]);
      }
    }
    // response sample fields if any
    return { path, bodyKeys: bodyKeys.slice(0, 40), len: md.length };
  }
  // field modules from metrics doc
  const metrics = get('https://sellfoxapi.apifox.cn/doc-8966970.md');
  const modules = [...metrics.matchAll(/fieldModule:\s*<CopyToClipboard>([A-Z0-9_]+)<\/CopyToClipboard>/g)].map(x => x[1]);
  // field names
  const fieldRows = [...metrics.matchAll(/\|\s*([^|\n]+)\s*\|\s*`?([a-zA-Z][a-zA-Z0-9_]*)`?\s*\|/g)].slice(0, 120).map(x => ({name: x[1].trim(), field: x[2].trim()}));
  // also try without backticks
  const fieldRows2 = [...metrics.matchAll(/\|\s*([^|]+?)\s*\|\s*([a-zA-Z][a-zA-Z0-9_]*)\s*\|\s*(true|false)/g)].map(x => ({name: x[1].trim(), field: x[2].trim(), compare: x[3]}));

  const sign = get('https://sellfoxapi.apifox.cn/doc-1749562.md');
  const errors = get('https://sellfoxapi.apifox.cn/doc-1759053.md');

  return {
    sign: sign,
    errors: errors,
    modules,
    fieldRows2: fieldRows2.slice(0, 150),
    apis: {
      productAnalyzeV2: extractApi(get('https://sellfoxapi.apifox.cn/api-474651907.md')),
      productSale: extractApi(get('https://sellfoxapi.apifox.cn/api-51516604.md')),
      shopByDay: extractApi(get('https://sellfoxapi.apifox.cn/api-146414432.md')),
      fbaStock: extractApi(get('https://sellfoxapi.apifox.cn/api-51516618.md')),
      review: extractApi(get('https://sellfoxapi.apifox.cn/api-119107035.md')),
      customReport: extractApi(get('https://sellfoxapi.apifox.cn/api-248307071.md')),
      spAdProduct: extractApi(get('https://sellfoxapi.apifox.cn/api-367482277.md')),
      onlineProductV2: extractApi(get('https://sellfoxapi.apifox.cn/api-420168353.md')),
    }
  };
}

